import{z as o,x as A,o as t,c as p,q as B,j as i,D as l,d as E,s,S as n,b as r}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"RM 校准","description":"","frontmatter":{"title":"RM 校准","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/rm-calibration.md","filePath":"llm/rm-calibration.md","lastUpdated":1791413859000}'),m={name:"llm/rm-calibration.md"};function d(D,a,P,C,b,h){const e=A("Mermaid");return t(),p("div",null,[a[2]||(a[2]=B('<h1 id="rm-校准" tabindex="-1">RM 校准 <a class="header-anchor" href="#rm-校准" aria-label="Permalink to &quot;RM 校准&quot;">​</a></h1><div class="epigraph"><p>奖励分数排得对，不等于 0.7 真表示七成会赢；未校准的标量一旦当概率用，阈值、加权和期望全歪。</p><footer>—— 对照 Guo 等神经网络校准；奖励模型上的胜率–分数关系见 InstructGPT 与后续 RewardBench 一类协议</footer></div><p><a href="/llm/rm-ensembles">上一课</a>用集成给出 \\(\\bar r\\) 与 \\(\\hat\\sigma\\)，策略可以避开成员打架的区域。缺口立刻出现：<strong>分歧小只说明看法一致，不说明分数的数值有概率含义。</strong> <a href="/llm/bradley-terry">Bradley-Terry</a> 把 \\(r\\) 差送进 \\(\\sigma\\)，训练只要求序正确；PPO 却把 \\(r\\) 当回报的绝对尺度。本课补校准。后课过优化默认：即使序对、数值也不等于金标。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>RM 损失推动的是 \\(r(y_w)-r(y_l)\\) 的符号，不是 \\(r\\) 的零点与单位。同一批比较，两份 RM 可以差一个仿射变换仍得相同交叉熵。接到 <a href="/llm/ppo-llm">PPO</a> 时，仿射会被优势归一化部分吃掉，但阈值规则吃不掉：安全门「\\(r\\gt 0\\) 才更新」、多目标加权、或把 \\(r\\) 当「人类会选的概率」，都会把未校准的零点当成决策。集成的 \\(\\hat\\sigma\\) 同样未校准——成员方差大，不代表真实误差大。</p><p>评测常用成对准确率。准确率高可以与校准差同时成立：高分段全挤在一个窄区间，低分段拖一条长尾。可靠性图（把预测胜率分桶，对照经验胜率）才会暴露。</p><p><span class="marginnote">「校准」翻译成大白话：让分数的数值有概率含义——RM 说 0.7，意思就该是「这类比较里大约七成会赢」。只排序不保数值的模型像只报名次的裁判：知道谁第一，但「第一领先多少」是拍的。阈值规则、多目标加权吃的都是数值，所以必须校准。</span></p><h3 id="校准的是哪一件事件" tabindex="-1">校准的是哪一件事件 <a class="header-anchor" href="#校准的是哪一件事件" aria-label="Permalink to &quot;校准的是哪一件事件&quot;">​</a></h3><p>要对齐的事件必须写明：是「标注员选 \\(y_a\\) 而不是 \\(y_b\\)」，还是「金标任务正确」，还是「Arena 裁判偏好」。RM 拟合的是第一种；产品门槛用的往往是第二种。用比较数据上的 Platt 缩放去校准准确率，是错对象。</p><p><span class="marginnote">InstructGPT 报告过 RM 与人类一致率，没有把 \\(r\\) 当成校准概率部署。后来把 RM 分数直接显示给用户当「质量」，已经换了语义。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>保留序的校准：在冻结的 RM 上，用一小份保留比较做温度缩放或 Platt，\\(r&#39; = a\\, r + b\\)，使</p> \\[\\hat p(y_a\\succ y_b)=\\sigma(r&#39;(y_a)-r&#39;(y_b)) \\]<p>匹配经验胜率。\\(a,b\\) 只在保留集上估，不许回流训练。分桶可靠性图与 ECE 是监控，不是训练损失。对 Best-of-N，校准改变的是「第几名之间的间隔」，不一定改变 argmax；对 PPO，校准改变优势的尺度，需与 <a href="/llm/reward-whitening">奖励白化</a> 一起看，不要叠两次仿射。</p><p><span class="marginnote">数字实例：未校准时 RM 给两答打分 \\(r_a=3.0\\)、\\(r_b=1.0\\)，\\(\\sigma(2.0)\\approx 0.88\\)——自称八成八会赢；若经验胜率只有六成，取温度 \\(a=0.4\\)，则 \\(\\sigma(0.4\\times 2.0)=\\sigma(0.8)\\approx 0.69\\)，与实际接近多了。\\(a,b\\) 只在保留集上估，不许回流训练。</span></p>',15)),(t(),i(n,null,{default:l(()=>[s(e,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20RM%5B%22%E5%86%BB%E7%BB%93%20RM%20%E5%88%86%E6%95%B0%20r%22%5D%20--%3E%20AFF%5B%22%E4%BF%9D%E7%95%99%E9%9B%86%E4%BB%BF%E5%B0%84%20%2F%20%E6%B8%A9%E5%BA%A6%22%5D%0A%20%20AFF%20--%3E%20P%5B%22%E6%A0%A1%E5%87%86%E8%83%9C%E7%8E%87%20%CF%83(%CE%94r')%22%5D%0A%20%20P%20--%3E%20TH%5B%22%E9%98%88%E5%80%BC%E4%B8%8E%E5%8A%A0%E6%9D%83%22%5D%0A%20%20P%20--%3E%20PPO%5B%22PPO%20%E5%9B%9E%E6%8A%A5%E5%B0%BA%E5%BA%A6%22%5D%0A%20%20GOLD%5B%22%E9%87%91%E6%A0%87%E4%BA%8B%E4%BB%B6%22%5D%20--%3E%20GAP%5B%22%E5%AF%B9%E8%B1%A1%E4%B8%8D%E4%B8%80%E8%87%B4%E5%88%99%E6%A0%A1%E5%87%86%E6%97%A0%E6%84%8F%E4%B9%89%22%5D%0A"})]),fallback:l(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=r("p",null,"集成之后可以对 \\(\\bar r\\) 做一次校准，不要对 \\(K\\) 个成员分别 Platt 再平均——后验混合与分别校准不可交换。若成员已悲观聚合，\\(\\lambda\\hat\\sigma\\) 再校准需要把惩罚项当作特征，而不是事后乘一个系数。",-1)),a[4]||(a[4]=r("h2",{id:"机制",tabindex:"-1"},[E("机制 "),r("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=r("p",null,"温度 \\(a\\lt 1\\) 压分数差，等于承认模型过自信：小 \\(\\Delta r\\) 不该对应极端胜率。PPO 里这会减小优势幅度、更新更温和，表面上更稳，也可能只是把学习率乘了一个隐式因子。因此校准后必须重扫 KL 系数与 clip，不能把「更稳」写成校准的因果效应。",-1)),a[6]||(a[6]=r("p",null,[E("可靠性图在分布外会坏。策略一更新，完成离开保留集，校准曲线过期。正确做法是周期性在"),r("strong",null,"当前策略样本"),E("上重估 \\(a,b\\)，或只把校准用于离线选优，不放进在线奖励。这与 InstructGPT 迭代标注 RM 是同一精神：分数的含义跟着分布走。")],-1)),a[7]||(a[7]=r("p",null,[r("span",{class:"marginnote"},"直觉类比：温度 \\(a\\lt 1\\) 像给过度的自信「退烧」——模型动辄给出 0.99 对 0.01 的悬殊比分，退烧后变成 0.7 对 0.3 这类更诚实的差距。注意名次没变，变的是领先幅度的说法：校准不改 argmax，改的是间隔与落在阈值附近的判断。")],-1)),(t(),i(n,null,{default:l(()=>[s(e,{id:"mermaid-57",class:"mermaid",graph:"flowchart%20TD%0A%20%20C%5B%22%E5%9C%A8%E4%BF%9D%E7%95%99%E9%9B%86%E4%B8%8A%E4%BC%B0%20a%2C%20b%22%5D%20--%3E%20V%5B%22%E6%A0%A1%E5%87%86%E6%9B%B2%E7%BA%BF%E5%BD%93%E4%B8%8B%E6%9C%89%E6%95%88%22%5D%0A%20%20P%5B%22%E7%AD%96%E7%95%A5%E7%BB%A7%E7%BB%AD%E6%9B%B4%E6%96%B0%22%5D%20--%3E%20D%5B%22%E6%96%B0%E6%A0%B7%E6%9C%AC%E5%88%86%E5%B8%83%E7%A6%BB%E5%BC%80%E4%BF%9D%E7%95%99%E9%9B%86%22%5D%0A%20%20D%20--%3E%20ST%5B%22%E6%97%A7%20a%2C%20b%20%E8%BF%87%E6%9C%9F%EF%BC%9A%E5%8F%AF%E9%9D%A0%E6%80%A7%E5%9B%BE%E5%8F%98%E5%BD%A2%22%5D%0A%20%20ST%20--%3E%20R%7B%22%E7%BB%AD%E6%9C%9F%E6%96%B9%E5%BC%8F%EF%BC%9F%22%7D%0A%20%20R%20--%3E%7C%22%E5%91%A8%E6%9C%9F%E9%87%8D%E4%BC%B0%22%7C%20RE%5B%22%E5%9C%A8%E5%BD%93%E5%89%8D%E7%AD%96%E7%95%A5%E6%A0%B7%E6%9C%AC%E4%B8%8A%E9%87%8D%E4%BC%B0%20a%2C%20b%22%5D%0A%20%20R%20--%3E%7C%22%E6%88%96%E9%80%80%E4%B8%80%E6%A1%A3%22%7C%20OFF%5B%22%E5%8F%AA%E5%81%9A%E7%A6%BB%E7%BA%BF%E9%80%89%E4%BC%98%EF%BC%8C%E4%B8%8D%E8%BF%9B%E5%9C%A8%E7%BA%BF%E5%A5%96%E5%8A%B1%22%5D%0A"})]),fallback:l(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[8]||(a[8]=B('<p><span class="marginnote">不要用生成式裁判的口头「置信」当校准。那是另一套未校准的语言，见后课 LLM 裁判。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p><a href="/llm/verifiable-reward">可验证奖励</a> 的 0/1 已经是事件本身，不需要 Platt；要校准的是「模型自报的对错概率」，不是 RM。DPO 没有显式 \\(r\\)，本课的仿射用不上，它的 \\(\\beta\\) 承担类似温度的角色，见 <a href="/llm/dpo">DPO</a>。校准不阻止 Goodhart：下一课把过优化写成标量奖励的命运，而不是「没校准好」。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>RM 训练保序，不保数值零点与单位；PPO 与阈值用的是数值。</li><li>在保留比较上做仿射 / 温度，使预测胜率对上经验胜率。</li><li>校准对象必须等于决策事件；分布一移，校准过期。</li><li>校准后要重扫 PPO 超参，避免把缩放当成算法改进。</li><li>出处：Guo 等校准；Ouyang 等 InstructGPT 的一致率；集成课的分数仍需单独校准。</li></ul>',5))])}const F=o(m,[["render",d]]);export{f as __pageData,F as default};
